window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-82f8154a6f7eaf7e"]={"versions": [{"id": "FIG-82f8154a6f7eaf7e", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur detaillierten Spezifikation des internen Teilschritts „Write DataID“ innerhalb der Funktion <code>E2E_P04mForward()</code>. Die Funktion ist Bestandteil des E2E-Profils 4m (<code>E2EProfile4m</code>) der AUTOSAR E2E-Bibliothek (Classic &amp; Adaptive Platform) zur Weiterleitung von Botschaften mit E2E-Schutz unter Fehlersignalisierung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Funktion: <code>E2E_P04mForward()</code> (gekennzeichnet als aufrufbarer Teilschritt bzw. Aktivität)\n</li><li>Zustands- und Konfigurationsparameter:\n<ul class=\"fig-list\"><li><code>ForwardStatus</code>: Statusvariable (Typenumeration bzw. Statusflag, geprüft auf den Zustand <code>E2E_P_ERROR</code>)\n</li><li><code>Config-&gt;DataID</code>: 4-Byte-Konfigurationswert der Datenidentifikation\n</li><li><code>Config-&gt;DataID+1</code>: Inkrementierter 4-Byte-Wert zur gezielten Fehlersignalisierung\n</li><li><code>Data[]</code>: Byte-Array des Nutzdatenpuffers\n</li><li><code>Offset</code>: Konfigurierter Byte-Offset des E2E-Headers im Datenpuffer\n</li></ul>\n</li><li>Verzweigungsknoten (Decision Node) und Zusammenführungsknoten (Merge Node)\n</li><li>Startknoten (Initial Node) und Endknoten (Activity Final Node)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Start der Aktivität am Initial Node nach Eintritt in den Schritt „Write DataID“.\n</li><li>Auswertung der Verzweigungsbedingung <code>if ForwardStatus == E2E_P_ERROR</code>:\n<ul class=\"fig-list\"><li>Zweig <code>[TRUE]</code>: Es wird der berechnete 4-Byte-Wert <code>Config-&gt;DataID+1</code> in Big-Endian-Bytereihenfolge in das Byte-Array <code>Data[Offset+4...Offset+7]</code> geschrieben.\n</li><li>Zweig <code>[FALSE]</code>: Es wird der reguläre 4-Byte-Wert <code>Config-&gt;DataID</code> in Big-Endian-Bytereihenfolge in das Byte-Array <code>Data[Offset+4...Offset+7]</code> geschrieben.\n</li></ul>\n</li><li>Zusammenführung beider Kontrollflusspfade am Merge Node.\n</li><li>Übergang in den Final Node zum Abschluss des Teilschritts.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß Anforderung [PRS_E2E_00771] ist das dargestellte Verhalten für den Teilschritt „Write DataID“ in <code>E2E_P04mForward()</code> normativ verbindlich. Bei Vorliegen eines Weiterleitungsfehlers (<code>ForwardStatus == E2E_P_ERROR</code>) wird die DataID gezielt um 1 modifiziert (<code>DataID + 1</code>), damit nachfolgende Empfänger beim E2E-Check einen Fehler erkennen. Die Serialisierung der 4-Byte-DataID muss zwingend in Big-Endian-Reihenfolge (Most Significant Byte zuerst) an den Bytepositionen <code>Offset+4</code> bis <code>Offset+7</code> erfolgen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-2ac96468cbb608f6", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur detaillierten Spezifikation des internen Teilschritts „Write DataID“ innerhalb der Funktion <code>E2E_P04mForward()</code>. Die Funktion ist Bestandteil des E2E-Profils 4m (<code>E2EProfile4m</code>) der AUTOSAR E2E-Bibliothek (Classic &amp; Adaptive Platform) zur Weiterleitung von Botschaften mit E2E-Schutz unter Fehlersignalisierung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Funktion: <code>E2E_P04mForward()</code> (gekennzeichnet als aufrufbarer Teilschritt bzw. Aktivität)\n</li><li>Zustands- und Konfigurationsparameter:\n<ul class=\"fig-list\"><li><code>ForwardStatus</code>: Statusvariable (Typenumeration bzw. Statusflag, geprüft auf den Zustand <code>E2E_P_ERROR</code>)\n</li><li><code>Config-&gt;DataID</code>: 4-Byte-Konfigurationswert der Datenidentifikation\n</li><li><code>Config-&gt;DataID+1</code>: Inkrementierter 4-Byte-Wert zur gezielten Fehlersignalisierung\n</li><li><code>Data[]</code>: Byte-Array des Nutzdatenpuffers\n</li><li><code>Offset</code>: Konfigurierter Byte-Offset des E2E-Headers im Datenpuffer\n</li></ul>\n</li><li>Verzweigungsknoten (Decision Node) und Zusammenführungsknoten (Merge Node)\n</li><li>Startknoten (Initial Node) und Endknoten (Activity Final Node)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Start der Aktivität am Initial Node nach Eintritt in den Schritt „Write DataID“.\n</li><li>Auswertung der Verzweigungsbedingung <code>if ForwardStatus == E2E_P_ERROR</code>:\n<ul class=\"fig-list\"><li>Zweig <code>[TRUE]</code>: Es wird der berechnete 4-Byte-Wert <code>Config-&gt;DataID+1</code> in Big-Endian-Bytereihenfolge in das Byte-Array <code>Data[Offset+4...Offset+7]</code> geschrieben.\n</li><li>Zweig <code>[FALSE]</code>: Es wird der reguläre 4-Byte-Wert <code>Config-&gt;DataID</code> in Big-Endian-Bytereihenfolge in das Byte-Array <code>Data[Offset+4...Offset+7]</code> geschrieben.\n</li></ul>\n</li><li>Zusammenführung beider Kontrollflusspfade am Merge Node.\n</li><li>Übergang in den Final Node zum Abschluss des Teilschritts.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß Anforderung [PRS_E2E_00771] ist das dargestellte Verhalten für den Teilschritt „Write DataID“ in <code>E2E_P04mForward()</code> normativ verbindlich. Bei Vorliegen eines Weiterleitungsfehlers (<code>ForwardStatus == E2E_P_ERROR</code>) wird die DataID gezielt um 1 modifiziert (<code>DataID + 1</code>), damit nachfolgende Empfänger beim E2E-Check einen Fehler erkennen. Die Serialisierung der 4-Byte-DataID muss zwingend in Big-Endian-Reihenfolge (Most Significant Byte zuerst) an den Bytepositionen <code>Offset+4</code> bis <code>Offset+7</code> erfolgen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-82f8154a6f7eaf7e", "to": "FIG-2ac96468cbb608f6", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
